-- ============================================
-- SEED — cours de seconde (programme 2026)
-- À coller dans : Supabase > SQL Editor > New query
-- ============================================
-- Contenu vérifié contre le texte officiel du programme de seconde
-- générale et technologique 2026 (vecteurs : ancien programme repris à
-- zéro pour la génération d'Anaïs ; valeur absolue limitée à la distance
-- et à |x - a| <= r ; fonctions de référence = valeur absolue, carré,
-- inverse). Chaque "contenu" est le JSON des blocs tel que l'éditeur de
-- cours (CoursEditor.jsx) les attend : [{id, type, content, titre?}].
-- Lancez ce script une seule fois : relancer créerait des doublons
-- (pas de contrainte d'unicité sur (niveau, chapitre)).

INSERT INTO cours (titre, matiere, niveau, chapitre, contenu, publie) VALUES
('Intervalles et ensembles de nombres', 'Mathématiques', '2nde', 'Intervalles et ensembles de nombres', $coursJson1$[{"id": 1, "type": "texte", "content": "Un intervalle est un morceau de la droite des nombres : tous les réels compris entre deux bornes."}, {"id": 2, "type": "definition", "content": "ℕ — entiers naturels — ex : 0, 1, 2, 57\nℤ — entiers relatifs — ex : −3, 0, 8\n𝔻 — décimaux (nombre fini de chiffres après la virgule) — ex : 0,25 ; −3,7 ; 12\nℚ — fractions de deux entiers — ex : 1/3 ; −7/4\nℝ — tous les nombres de la droite, irrationnels compris — ex : √2 ; π", "titre": "Les ensembles de nombres"}, {"id": 3, "type": "texte", "content": "Ces ensembles s'emboîtent : ℕ ⊂ ℤ ⊂ 𝔻 ⊂ ℚ ⊂ ℝ. 1/3 est rationnel mais pas décimal. √2 et π sont des réels qui ne sont pas rationnels (on dit irrationnels)."}, {"id": 4, "type": "definition", "content": "2 ≤ x ≤ 5  →  [2 ; 5]  (2 et 5 inclus)\n2 < x < 5  →  ]2 ; 5[  (2 et 5 exclus)\n2 ≤ x < 5  →  [2 ; 5[  (2 inclus, 5 exclu)\nx ≥ 2  →  [2 ; +∞[  (tout à partir de 2)\nx < 5  →  ]−∞ ; 5[  (tout avant 5)", "titre": "Les intervalles"}, {"id": 5, "type": "remarque", "content": "Un crochet tourné vers le nombre l'inclut, un crochet tourné vers l'extérieur l'exclut. ∞ a toujours un crochet vers l'extérieur, car on ne l'atteint jamais. On écrit x ∈ [2 ; 5] pour « x appartient à [2 ; 5] ».", "titre": "Règle des crochets"}, {"id": 6, "type": "definition", "content": "Intersection ∩ : les nombres qui sont dans les deux intervalles à la fois (« et »).\nRéunion ∪ : les nombres qui sont dans l'un ou l'autre (« ou »).", "titre": "Réunion et intersection"}, {"id": 7, "type": "exemple", "content": "[1 ; 5] ∩ [3 ; 8] = [3 ; 5]\n[1 ; 3] ∪ [2 ; 6] = [1 ; 6]\n]−∞ ; 2[ ∪ [2 ; +∞[ = ℝ\n]−∞ ; 2[ ∩ [2 ; +∞[ = ∅  (2 est dans le deuxième mais pas dans le premier)", "titre": "Pour ne pas se tromper : dessiner les deux intervalles sur la même droite"}, {"id": 8, "type": "remarque", "content": "Oublier le sens du crochet : ]2 ; 5] et [2 ; 5] ne sont pas le même ensemble.\nÉcrire [2 ; 5] ∩ [7 ; 9] = [5 ; 7] : il n'y a aucun point commun, c'est ∅.\nPour une égalité comme x = 3 ou x = 5, on n'écrit pas un intervalle : on liste les deux valeurs, {3 ; 5}.", "titre": "Pièges classiques"}, {"id": 9, "type": "exemple", "content": "1) Écrire 2 ≤ x < 7 avec un intervalle.  →  [2 ; 7[\n2) Calculer ]−∞ ; 1] ∩ [−3 ; 5].  →  [−3 ; 1]", "titre": "Entraîne-toi (sans regarder au-dessus)"}]$coursJson1$, true),

('Valeur absolue et distance', 'Mathématiques', '2nde', 'Valeur absolue et distance', $coursJson2$[{"id": 1, "type": "texte", "content": "La valeur absolue d'un nombre, c'est sa distance à zéro sur la droite : on enlève le signe."}, {"id": 2, "type": "formule", "content": "|x| = \\begin{cases} x & \\text{si } x \\geq 0 \\\\ -x & \\text{si } x \\leq 0 \\end{cases}"}, {"id": 3, "type": "exemple", "content": "Exemples : |5| = 5, |−3| = 3, |0| = 0. Une valeur absolue n'est jamais négative."}, {"id": 4, "type": "definition", "content": "Sur la droite graduée, la distance entre a et b est la valeur absolue de leur différence :", "titre": "Distance entre deux nombres"}, {"id": 5, "type": "formule", "content": "d(a ; b) = |a - b| = |b - a|"}, {"id": 6, "type": "exemple", "content": "La distance entre −2 et 5 vaut |−2 − 5| = |−7| = 7."}, {"id": 7, "type": "theoreme", "content": "|x − a| est la distance entre x et a. On lit |x − a| comme « la distance de x au point a ». C'est cette lecture qui permet de résoudre toutes les équations et inéquations avec valeur absolue.", "titre": "Le lien clé du chapitre"}, {"id": 8, "type": "definition", "content": "|x − a| = r  →  x = a − r ou x = a + r  (les deux points à distance r de a)\n|x − a| ≤ r  →  x ∈ [a − r ; a + r]  (les points à distance au plus r de a)\n|x − a| ≥ r  →  x ∈ ]−∞ ; a − r] ∪ [a + r ; +∞[  (les points à distance au moins r de a)", "titre": "Résoudre avec une valeur absolue (r positif)"}, {"id": 9, "type": "remarque", "content": "Les versions strictes (< et >) suivent la même logique avec des crochets ouverts. Attention : le programme officiel de seconde ne demande que la distance entre deux nombres et le cas |x − a| ≤ r (intervalle de centre a). Les cas égalité et ≥ sont des compléments utiles, mais pas exigibles au contrôle."}, {"id": 10, "type": "exemple", "content": "|x − 3| = 2 : on cherche les nombres à distance 2 de 3. x = 1 ou x = 5.\n|x − 3| ≤ 2 : à distance au plus 2 de 3. x ∈ [1 ; 5].\n|x + 1| < 3 : on écrit |x − (−1)| < 3, donc à distance moins de 3 de −1. x ∈ ]−4 ; 2[.\n|x| = −2 : impossible, une valeur absolue n'est jamais négative. Aucune solution.", "titre": "Exemples résolus"}, {"id": 11, "type": "remarque", "content": "Pour |x + 1|, le centre est −1, pas +1 : il faut réécrire x + 1 en x − (−1).\n|a + b| n'est pas égal à |a| + |b| en général. Exemple : |3 + (−5)| = 2, mais |3| + |−5| = 8.\nUne distance est toujours positive : jamais de résultat négatif.", "titre": "Pièges classiques"}]$coursJson2$, true),

('Inéquations du premier degré', 'Mathématiques', '2nde', 'Inéquations du premier degré', $coursJson3$[{"id": 1, "type": "texte", "content": "Résoudre une inéquation, c'est trouver tous les nombres x qui la rendent vraie. On procède comme pour une équation, avec une seule règle en plus. La réponse est un intervalle, pas un nombre."}, {"id": 2, "type": "theoreme", "content": "On peut ajouter ou soustraire le même nombre des deux côtés : le sens de l'inégalité ne change pas.\nOn peut multiplier ou diviser par un nombre positif : le sens ne change pas.\nQuand on multiplie ou divise par un nombre négatif, on inverse le sens de l'inégalité.", "titre": "Les règles"}, {"id": 3, "type": "remarque", "content": "Pourquoi : 2 < 5, mais en multipliant par −1 on obtient −2 > −5. Les nombres se rangent dans l'ordre inverse."}, {"id": 4, "type": "methode", "content": "1. Développer s'il y a des parenthèses (attention au signe moins devant).\n2. Mettre les x d'un côté et les nombres de l'autre, en changeant les signes de ceux qu'on déplace.\n3. Diviser par le coefficient de x, en inversant le sens s'il est négatif.\n4. Écrire la solution sous forme d'intervalle.", "titre": "Méthode"}, {"id": 5, "type": "exemple", "content": "3x − 5 ≤ 7 : 3x ≤ 12, donc x ≤ 4. Solution : ]−∞ ; 4].\n−2x + 1 > 7 : −2x > 6. On divise par −2, donc on inverse : x < −3. Solution : ]−∞ ; −3[.\n2x + 1 ≥ 5x − 8 : 2x − 5x ≥ −8 − 1, donc −3x ≥ −9. On divise par −3 : x ≤ 3. Solution : ]−∞ ; 3].\n4(x − 2) < 3x + 5 : 4x − 8 < 3x + 5, donc x < 13. Solution : ]−∞ ; 13[.\nDouble inégalité −3 < 2x + 1 ≤ 7 : on retire 1 partout, −4 < 2x ≤ 6, puis on divise par 2 : −2 < x ≤ 3. Solution : ]−2 ; 3].", "titre": "Exemples résolus"}, {"id": 6, "type": "methode", "content": "Pour 2x + 1 ≥ 5x − 8, on teste x = 0 (dans la solution ]−∞ ; 3]) : 1 ≥ −8, vrai. On teste x = 4 (hors solution) : 9 ≥ 12, faux. Les deux tests concordent, la solution est cohérente.", "titre": "Vérifier avec une valeur test"}, {"id": 7, "type": "remarque", "content": "Oublier d'inverser le sens en divisant par un négatif. C'est l'erreur n°1.\nSe tromper de crochet : ≤ et ≥ donnent un crochet fermé, < et > un crochet ouvert.\nÉcrire la solution sous la forme x = 4 : une inéquation a un ensemble de solutions, pas une seule valeur.", "titre": "Pièges classiques"}]$coursJson3$, true),

('Vecteurs : l''essentiel', 'Mathématiques', '2nde', 'Vecteurs dans le plan', $coursJson4$[{"id": 1, "type": "texte", "content": "Un vecteur est un déplacement. $\\overrightarrow{AB}$, c'est aller de A à B. Trois informations : direction, sens, longueur."}, {"id": 2, "type": "definition", "content": "Deux vecteurs sont égaux s'ils ont la même direction, le même sens et la même longueur — peu importe où on les dessine.", "titre": "Deux vecteurs égaux"}, {"id": 3, "type": "definition", "content": "Translation de vecteur u : chaque point glisse de la même flèche. L'image de A est A' tel que $\\overrightarrow{AA'}$ = $\\vec{u}$. La figure ne change ni de forme ni de taille.", "titre": "Translation"}, {"id": 4, "type": "theoreme", "content": "ABCD est un parallélogramme si et seulement si $\\overrightarrow{AB}$ = $\\overrightarrow{DC}$. On lit les lettres dans l'ordre du tour.", "titre": "Parallélogramme"}, {"id": 5, "type": "theoreme", "content": "$\\overrightarrow{AB}$ + $\\overrightarrow{BC}$ = $\\overrightarrow{AC}$. On enchaîne les flèches, la lettre du milieu disparaît.", "titre": "Relation de Chasles"}, {"id": 6, "type": "definition", "content": "$\\overrightarrow{AB}$ a pour coordonnées (x_B − x_A ; y_B − y_A). Toujours arrivée moins départ.", "titre": "Coordonnées"}, {"id": 7, "type": "methode", "content": "Pour additionner deux vecteurs, on additionne leurs coordonnées une à une. Pour multiplier un vecteur par un nombre, on multiplie chacune de ses coordonnées par ce nombre.", "titre": "Somme et multiple"}, {"id": 8, "type": "definition", "content": "La norme de $\\overrightarrow{AB}$, notée ‖$\\overrightarrow{AB}$‖, vaut $\\sqrt{x^2+y^2}$ où (x ; y) sont les coordonnées de $\\overrightarrow{AB}$. C'est aussi la distance AB.", "titre": "Norme"}, {"id": 9, "type": "definition", "content": "Les coordonnées du milieu d'un segment sont les moyennes de celles des deux extrémités.", "titre": "Milieu"}, {"id": 10, "type": "exemple", "content": "A(1 ; 2) et B(4 ; 6). $\\overrightarrow{AB}$ (4 − 1 ; 6 − 2) = (3 ; 4). Norme : √(3² + 4²) = √25 = 5. Milieu de [AB] : ((1+4)/2 ; (2+6)/2) = (2,5 ; 4).", "titre": "Exemple résolu"}, {"id": 11, "type": "remarque", "content": "Lire les lettres dans le mauvais ordre : pour ABCD, c'est $\\overrightarrow{AB}$ = $\\overrightarrow{DC}$, pas $\\overrightarrow{AB}$ = $\\overrightarrow{CD}$.\nFaire départ moins arrivée au lieu d'arrivée moins départ : la coordonnée change de signe.\nOublier les parenthèses avec un négatif : 5 − (−2) = 7, pas 3.", "titre": "Pièges classiques"}, {"id": 12, "type": "remarque", "content": "La flèche se note toujours au-dessus des lettres : $\\overrightarrow{AB}$, jamais AB tout court. C'est sanctionné si elle manque.", "titre": "Pour le contrôle"}, {"id": 13, "type": "exemple", "content": "La colinéarité (deux vecteurs colinéaires si l'un est un multiple de l'autre), le déterminant pour la tester, puis les équations de droites. À confirmer avec le cahier qu'il n'y en a pas au prochain contrôle.", "titre": "Ce qui vient après (pas pour cette interro)"}]$coursJson4$, true);
